        date_str = r["Date"].strip()
        price_str = r["Crude_Oil_Price"].strip()
        if date_str and price_str:
            rows.append({
                "date": datetime.strptime(date_str, "%Y-%m-%d"),
                "price": float(price_str)
            })

rows.sort(key=lambda x: x["date"])
N = len(rows)
prices = [r["price"] for r in rows]
dates = [r["date"] for r in rows]

# --- Basic statistics ---
min_price = min(prices)
max_price = max(prices)
min_idx = prices.index(min_price)
max_idx = prices.index(max_price)
price_range = max_price - min_price
mean_price = sum(prices) / N
sorted_prices = sorted(prices)
median_price = sorted_prices[N // 2] if N % 2 == 1 else (sorted_prices[N // 2 - 1] + sorted_prices[N // 2]) / 2
variance = sum((p - mean_price) ** 2 for p in prices) / (N - 1)
std_dev = math.sqrt(variance)

# Percentiles
def percentile(data, pct):
    k = (len(data) - 1) * pct / 100
    f = math.floor(k)
    c = math.ceil(k)
    if f == c:
        return data[int(k)]
    return data[f] * (c - k) + data[c] * (k - f)

p10 = percentile(sorted_prices, 10)
p25 = percentile(sorted_prices, 25)
p75 = percentile(sorted_prices, 75)
p90 = percentile(sorted_prices, 90)

# --- CAGR ---
first_price = rows[0]["price"]
last_price = rows[-1]["price"]
first_date = rows[0]["date"]
last_date = rows[-1]["date"]
years_span = (last_date - first_date).days / 365.25
cagr = (last_price / first_price) ** (1 / years_span) - 1

# --- Month-over-month changes ---
mom_abs = []
mom_pct = []
for i in range(1, N):
    abs_chg = rows[i]["price"] - rows[i - 1]["price"]
    pct_chg = abs_chg / rows[i - 1]["price"] * 100 if rows[i - 1]["price"] != 0 else 0
    mom_abs.append({
        "date": rows[i]["date"],
        "prev_price": rows[i - 1]["price"],
        "curr_price": rows[i]["price"],
        "abs_change": abs_chg,
        "pct_change": pct_chg,
    })
    mom_pct.append(pct_chg)

# Max absolute increase and decrease
mom_abs_sorted = sorted(mom_abs, key=lambda x: x["abs_change"])
max_abs_increase = mom_abs_sorted[-1]
max_abs_decrease = mom_abs_sorted[0]

# Max percentage increase and decrease
mom_pct_sorted = sorted(mom_abs, key=lambda x: x["pct_change"])
max_pct_increase = mom_pct_sorted[-1]
max_pct_decrease = mom_pct_sorted[0]

# MoM volatility (std of pct changes)
mean_pct = sum(mom_pct) / len(mom_pct)
mom_std = math.sqrt(sum((p - mean_pct) ** 2 for p in mom_pct) / (len(mom_pct) - 1))

# --- Top 10 largest absolute MoM moves ---
