# --- Decade-by-decade analysis ---
decades = {}
decade_labels = ["1970s", "1980s", "1990s", "2000s", "2010s", "2020s"]
for r in rows:
    year = r["date"].year
    if year < 1980:
        dec = "1970s"
    elif year < 1990:
        dec = "1980s"
    elif year < 2000:
        dec = "1990s"
    elif year < 2010:
        dec = "2000s"
    elif year < 2020:
        dec = "2010s"
    else:
        dec = "2020s"
    if dec not in decades:
        decades[dec] = []
    decades[dec].append(r["price"])

decade_stats = {}
for dec in decade_labels:
    dp = decades.get(dec, [])
    if not dp:
        continue
    d_mean = sum(dp) / len(dp)
    d_min = min(dp)
    d_max = max(dp)
    d_var = sum((p - d_mean) ** 2 for p in dp) / (len(dp) - 1) if len(dp) > 1 else 0
    d_std = math.sqrt(d_var)
    decade_stats[dec] = {
        "mean": d_mean,
        "min": d_min,
        "max": d_max,
        "std": d_std,
        "count": len(dp),
        "range": d_max - d_min,
    }

highest_avg_decade = max(decade_stats.items(), key=lambda x: x[1]["mean"])

