yearly_avg = defaultdict(list)
for r in rows:
    yearly_avg[r["date"].year].append(r["price"])
yearly_avg = {y: sum(p) / len(p) for y, p in yearly_avg.items()}
yearly_sorted = sorted(yearly_avg.items())

yoy_changes = []
for i in range(1, len(yearly_sorted)):
    y_prev, p_prev = yearly_sorted[i - 1]
    y_curr, p_curr = yearly_sorted[i]
    chg = (p_curr - p_prev) / p_prev * 100
    yoy_changes.append({"year": y_curr, "prev_avg": p_prev, "curr_avg": p_curr, "pct_change": chg})

top_yoy_increases = sorted(yoy_changes, key=lambda x: x["pct_change"], reverse=True)[:5]
top_yoy_decreases = sorted(yoy_changes, key=lambda x: x["pct_change"])[:5]

